private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    try {
        while (bb.hasRemaining()) {
            int b1 = bb.get() & 0xFF;
            if (b1 < 0x80) {
                sb.append((char) b1);
                i++;
            } else if ((b1 >> 5) == 0x6) { // 2-byte sequence
                if (bb.remaining() < 1) break;
                int b2 = bb.get() & 0x3F;
                int codepoint = ((b1 & 0x1F) << 6) | b2;
                sb.append((char) codepoint);
                i++;
            } else if ((b1 >> 4) == 0xE) { // 3-byte sequence
                if (bb.remaining() < 2) break;
                int b2 = bb.get() & 0x3F;
                int b3 = bb.get() & 0x3F;
                int codepoint = ((b1 & 0x0F) << 12) | (b2 << 6) | b3;
                sb.append((char) codepoint);
                i++;
            } else if ((b1 >> 3) == 0x1E) { // 4-byte sequence
                if (bb.remaining() < 3) break;
                int b2 = bb.get() & 0x3F;
                int b3 = bb.get() & 0x3F;
                int b4 = bb.get() & 0x3F;
                int codepoint = ((b1 & 0x07) << 18) | (b2 << 12) | (b3 << 6) | b4;
                // Convert to surrogate pair
                codepoint -= 0x10000;
                char high = (char) ((codepoint >> 10) + 0xD800);
                char low = (char) ((codepoint & 0x3FF) + 0xDC00);
                sb.append(high).append(low);
                i += 2;
            } else {
                // Malformed leading byte, replace with �
                sb.append('\uFFFD');
                i++;
            }
        }
        return i;
    } catch (BufferUnderflowException e) {
        // Incomplete sequence, return current index without discarding any bytes
        return i;
    } catch (IllegalArgumentException e) {
        // Handle any unexpected decoding errors gracefully
        sb.append('\uFFFD');
        return i + 1;
    }
}

