private void enlarge(final int size){
    if (size <= 0) {
        return;
    }
    try {
        int oldCapacity = buffer.length;
        // Ensure new capacity can hold current data + requested additional size
        int required = this.size + size;
        int newCapacity = Math.max(oldCapacity * 2, required);
        if (newCapacity <= 0) { // guard against overflow
            newCapacity = Integer.MAX_VALUE;
        }
        byte[] newBuffer = new byte[newCapacity];
        System.arraycopy(buffer, 0, newBuffer, 0, this.size);
        buffer = newBuffer;
    } catch (OutOfMemoryError e) {
        // In a real implementation you might wrap this in a custom exception
        throw new RuntimeException("Failed to enlarge byte vector", e);
    }
}

