public static int nullSafeHashCode(long[] array){
    if (array == null) {
        return 0;
    }
    int hash = 1;
    for (long value : array) {
        hash = 31 * hash + Long.hashCode(value);
    }
    return hash;
}

private TreeNode<T> rotateRight(TreeNode<T> node){
    // Return immediately if node is null or has no left subtree to rotate
    if (node == null || node.left == null) {
        return node;
    }
    try {
        TreeNode<T> leftChild = node.left;
        TreeNode<T> leftRight = leftChild.right;

        // Detach leftChild from node
        node.left = leftRight;
        if (leftRight != null) {
            leftRight.parent = node;
        }

        // Set leftChild as new parent of the original node
        leftChild.right = node;
        leftChild.parent = node.parent;
        node.parent = leftChild;

        // Update the original parent's reference to point to leftChild
        if (leftChild.parent != null) {
            if (leftChild.parent.left == node) {
                leftChild.parent.left = leftChild;
            } else if (leftChild.parent.right == node) {
                leftChild.parent.right = leftChild;
            }
        }

        return leftChild;
    } catch (Exception e) {
        // In case of any unexpected errors, log and return the original node
        // (Assuming a LOG object exists in the surrounding class context)
        if (LOG != null) {
            LOG.log(Level.SEVERE, "Failed to perform right rotation on node", e);
        }
        return node;
    }
}

