public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null) {
        throw new IllegalArgumentException("OutputStream cannot be null");
    }
    if (message == null) {
        throw new IllegalArgumentException("Message cannot be null");
    }
    if (schema == null) {
        throw new IllegalArgumentException("Schema cannot be null");
    }
    if (buffer == null) {
        throw new IllegalArgumentException("LinkedBuffer cannot be null");
    }
    // Serialize the message to a byte array using the provided schema and buffer
    byte[] bytes;
    try {
        bytes = schema.toByteArray(message, buffer);
    } catch (RuntimeException e) {
        throw new IOException("Failed to serialize message", e);
    }
    int size = bytes.length;

    // Write the length as a varint followed by the message bytes
    CodedOutputStream cos = CodedOutputStream.newInstance(out);
    try {
        cos.writeUInt32NoTag(size);
        cos.writeRawBytes(bytes);
        cos.flush();
    } catch (IOException e) {
        throw e;
    }

    return size;
}

