        if (offset < 0 || offset + 8 > data.length) {
            throw new IllegalArgumentException("Invalid offset");
        }
        long high = this.readInt(offset) & 0xFFFFFFFFL;
        long low = this.readInt(offset + 4) & 0xFFFFFFFFL;
        return (high << 32) | low;
    } catch (Exception e) {
        throw new RuntimeException(e);
    }
}

