protected List<TimeRange> buildTimeRanges(long start, long end){
    List<TimeRange> ranges = new ArrayList<>();
    if (start >= end) {
        return ranges;
    }
    if (FETCH_DATA_DURATION <= 0) {
        // fall back to a single range if the duration threshold is not positive
        ranges.add(new TimeRange(start, end));
        return ranges;
    }
    for (long s = start; s < end; s += FETCH_DATA_DURATION) {
        long e = Math.min(s + FETCH_DATA_DURATION, end);
        ranges.add(new TimeRange(s, e));
    }
    return ranges;
}

