static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        return timeBucket;
    }
    try {
        int year = (int) (timeBucket / 10000);
        int month = (int) ((timeBucket % 10000) / 100);
        int day = (int) (timeBucket % 100);
        int bucketStart = ((day - 1) / dayStep) * dayStep + 1;
        return year * 10000L + month * 100L + bucketStart;
    } catch (Exception e) {
        // If parsing fails, return the original value.
        return timeBucket;
    }
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new NullPointerException("str is null");
    }
    int strLen = str.length();
    if (index < 0 || len < 0 || index + len > strLen) {
        throw new IndexOutOfBoundsException("Invalid index or length");
    }
    int count = 0;
    int i = index;
    int end = index + len;
    while (i < end) {
        int cp = str.codePointAt(i);
        int charCount = Character.charCount(cp);
        if (i + charCount > end) {
            throw new IndexOutOfBoundsException("Incomplete surrogate pair");
        }
        if (cp <= 0x7F) {
            count += 1;
        } else if (cp <= 0x7FF) {
            count += 2;
        } else if (cp <= 0xFFFF) {
            count += 3;
        } else {
            count += 4;
        }
        i += charCount;
    }
    return count;
}

