public void removeFromTreeEdgeList(){
    try {
        // unlink from source node's outgoing list
        if (prevFrom != null) {
            prevFrom.nextFrom = nextFrom;
        }
        if (nextFrom != null) {
            nextFrom.prevFrom = prevFrom;
        }

        // unlink from destination node's incoming list
        if (prevTo != null) {
            prevTo.nextTo = nextTo;
        }
        if (nextTo != null) {
            nextTo.prevTo = prevTo;
        }

        // clear this edge's own links
        prevFrom = nextFrom = prevTo = nextTo = null;
    } catch (Exception e) {
        // swallow silently or log a warning
        // (the surrounding context might provide a logger)
    }
}

public static String findAndSubst(String key, Properties props){
    if (key == null || props == null) {
        return null;
    }
    String value = props.getProperty(key);
    if (value == null) {
        return null;
    }
    String result = value;
    try {
        int start = result.indexOf("${");
        while (start != -1) {
            int end = result.indexOf("}", start + 2);
            if (end == -1) {
                break; // unmatched ${, stop processing
            }
            String placeholder = result.substring(start + 2, end);
            String replacement = props.getProperty(placeholder, "");
            result = result.substring(0, start) + replacement + result.substring(end + 1);
            start = result.indexOf("${");
        }
    } catch (Exception e) {
        // In case of any unexpected issue, return the original or an empty string
