private static boolean endsWith(final String str, final String suffix, final boolean ignoreCase){
    if (str == null && suffix == null) {
        return true;
    }
    if (str == null || suffix == null) {
        return false;
    }
    int strLen = str.length();
    int suffixLen = suffix.length();
    if (suffixLen > strLen) {
        return false;
    }
    if (ignoreCase) {
        return str.regionMatches(true, strLen - suffixLen, suffix, 0, suffixLen);
    } else {
        return str.endsWith(suffix);
    }
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode){
    if (u == null) {
        throw new IllegalArgumentException("URI cannot be null");
    }
    String rawPath = u.getRawPath();
    if (rawPath == null || rawPath.isEmpty()) {
        return java.util.Collections.emptyList();
    }
    if (rawPath.startsWith("/")) {
        rawPath = rawPath.substring(1);
    }
    java.util.List<PathSegmentImpl> segments = new java.util.ArrayList<>();
    String[] parts = rawPath.split("/", -1);
    for (String part : parts) {
        if (part.isEmpty()) {
            continue;
        }
        String segment;
        if (decode) {
            try {
                segment = java.net.URLDecoder.decode(part, java.nio.charset.StandardCharsets.UTF_8.name());
            } catch (Exception e) {
                segment = part;
            }
        } else {
            segment = part;
        }
        segments.add(new PathSegmentImpl(segment));
    }
    return segments;
}

