private void pop(final String descriptor) {
    if (descriptor == null) {
        throw new IllegalArgumentException("Descriptor must not be null");
    }
    int start = descriptor.indexOf('(');
    int end = descriptor.indexOf(')', start);
    if (start == -1 || end == -1) {
        throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
    }
    int count = 0;
    for (int i = start + 1; i < end; ) {
        char c = descriptor.charAt(i);
        switch (c) {
            case '[':
                while (descriptor.charAt(i) == '[') {
                    i++;
                }
                c = descriptor.charAt(i);
                if (c == 'L') {
                    i++;
                    while (descriptor.charAt(i) != ';') i++;
                    i++; // skip ';'
                } else {
                    i++; // primitive
                }
                count++; // an array occupies a single slot
                break;
            case 'L':
                i++; // skip 'L'
                while (descriptor.charAt(i) != ';') i++;
                i++; // skip ';'
                count++; // object occupies a single slot
                break;
            case 'J':
            case 'D':
                count += 2; // long and double occupy two slots
                i++;
                break;
            case 'V':
                i++; // void, no slot
                break;
            default:
                count++; // other primitives occupy a single slot
                i++;
                break;
        }
    }
    // Pop the computed number of elements from the output stack
    for (int j = 0; j < count; j++) {
        outputStack.remove(outputStack.size() - 1);
    }
}

@Override public void write(final byte b[],final int off,final int len) throws IOException {
    if (b == null) {
        throw new NullPointerException("byte array is null");
    }
    if (off < 0 || len < 0 || off > b.length - len) {
        throw new IndexOutOfBoundsException("Invalid offset or length");
    }
    int newCount = count + len;
    if (newCount > buf.length) {
        byte[] newBuf = new byte[(newCount >> 1) + newCount];
        System.arraycopy(buf, 0, newBuf, 0, count);
        buf = newBuf;
    }
    System.arraycopy(b, off, buf, count, len);
    count = newCount;
}

public static final <V> void swap(V[] arr, int i, int j) {
    if (arr == null) {
        throw new IllegalArgumentException("Array must not be null");
    }
    int n = arr.length;
    if (i < 0 || i >= n || j < 0 || j >= n) {
        throw new IndexOutOfBoundsException("Index out of bounds: i=" + i + ", j=" + j);
    }
    if (i == j) {
        return;
    }
    V temp = arr[i];
    arr[i] = arr[j];
    arr[j] = temp;
}

