@Override protected Object convertToType(final Class<?> type,final Object value) throws Exception {
    // Ensure target type is Character or primitive char
    if (!(Character.class.isAssignableFrom(type) || type == char.class)) {
        throw new IllegalArgumentException("Target type must be Character or char, but was: " + type.getName());
    }
    if (value == null) {
        return null;
    }
    if (value instanceof Character) {
        return value; // already a Character
    }
    if (value instanceof String) {
        String str = (String) value;
        if (str.length() == 1) {
            return str.charAt(0); // autobox to Character
        }
        throw new IllegalArgumentException("String cannot be converted to Character (length != 1): " + str);
    }
    if (value instanceof Number) {
        int intVal = ((Number) value).intValue();
        if (intVal < Character.MIN_VALUE || intVal > Character.MAX_VALUE) {
            throw new IllegalArgumentException("Number value out of character range: " + intVal);
        }
        return (char) intVal; // autobox to Character
    }
    throw new IllegalArgumentException("Cannot convert type " + value.getClass().getName() + " to Character");
}

