public static int nextPrime(int desiredCapacity){
    if (desiredCapacity <= 2) return 2;
    // Ensure we start at an odd number
    int candidate = desiredCapacity % 2 == 0 ? desiredCapacity + 1 : desiredCapacity;
    if (candidate <= 2) candidate = 3;
    // Upper bound within 11% if applicable
    long maxCandidate;
    if (desiredCapacity >= 1000) {
        maxCandidate = (long)(desiredCapacity * 1.11) + 10;
    } else {
        maxCandidate = Integer.MAX_VALUE;
    }
    while (candidate <= maxCandidate && candidate > 0) {
        if (isPrime(candidate)) return candidate;
        candidate += 2; // next odd number
    }
    // If upper bound exceeded, continue searching beyond bound until Integer.MAX_VALUE
    while (candidate > 0 && candidate >= 0) { // candidate positive
        if (isPrime(candidate)) return candidate;
        candidate += 2;
        if (candidate < 0) break; // overflow
    }
    // Should never reach here
    return -1;
}

private static boolean isPrime(int n){
    if (n <= 1) return false;
    if (n <= 3) return true;
    if (n % 2 == 0 || n % 3 == 0) return false;
    for (int i = 5; (long)i * i <= n; i += 6) {
        if (n % i == 0 || n % (i + 2) == 0) return false;
    }
    return true;
}

