@Override public String readString() throws IOException {
    // Assume there is a DataInput named 'in' available in this class.
    // Read the string length first.  A negative length indicates a null value.
    int length = in.readInt();
    if (length < 0) {
        return null;
    }
    // Allocate buffer and read the specified number of bytes.
    byte[] bytes = new byte[length];
    int offset = 0;
    while (offset < length) {
        int read = in.read(bytes, offset, length - offset);
        if (read == -1) {
            throw new EOFException("Unexpected end of stream while reading string of length " + length);
        }
        offset += read;
    }
    // Convert the byte array to a UTF‑8 string and return it.
    return new String(bytes, java.nio.charset.Charset.forName("UTF-8"));
}

