public final byte[] toByteArray(){
    if (buffers == null || buffers.length == 0) {
        return new byte[0];
    }
    int totalSize = 0;
    for (ByteBuffer buf : buffers) {
        totalSize += buf.remaining();
    }
    byte[] result = new byte[totalSize];
    int offset = 0;
    for (ByteBuffer buf : buffers) {
        int len = buf.remaining();
        buf.mark();
        buf.get(result, offset, len);
        offset += len;
        buf.reset();
    }
    return result;
}

public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder(str.length());
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);
        if (c == '\\' && i + 1 < str.length()) {
            char next = str.charAt(++i);
            switch (next) {
                case 'b':
                    sb.append('\b');
                    break;
                case 't':
                    sb.append('\t');
                    break;
                case 'n':
                    sb.append('\n');
                    break;
                case 'f':
                    sb.append('\f');
                    break;
                case 'r':
                    sb.append('\r');
                    break;
                case '\"':
                    sb.append('\"');
                    break;
                case '\'':
                    sb.append('\'');
                    break;
                case '\\':
                    sb.append('\\');
                    break;
                case 'u':
                    if (i + 4 >= str.length()) {
                        throw new IllegalArgumentException("Incomplete Unicode escape");
                    }
                    String hex = str.substring(i + 1, i + 5);
                    try {
                        int code = Integer.parseInt(hex, 16);
                        sb.append((char) code);
                    } catch (NumberFormatException e) {
                        throw new IllegalArgumentException("Invalid Unicode escape: \\u" + hex);
                    }
                    i += 4;
                    break;
                case 'x':
                    int j = i + 1;
                    int limit = Math.min(j + 4, str.length());
                    StringBuilder hexSB = new StringBuilder();
                    while (j < limit && Character.digit(str.charAt(j), 16) != -1) {
                        hexSB.append(str.charAt(j));
                        j++;
                    }
                    if (hexSB.length() == 0) {
                        throw new IllegalArgumentException("Invalid hexadecimal escape: \\x");
                    }
                    int codeHex = Integer.parseInt(hexSB.toString(), 16);
                    sb.append((char) codeHex);
                    i = j - 1;
                    break;
                default:
                    if (next >= '0' && next <= '7') {
                        int val = next - '0';
                        int count = 1;
                        while (count < 3 && i + 1 < str.length()) {
                            char d = str.charAt(i + 1);
                            if (d < '0' || d > '7') {
                                break;
                            }
                            val = val * 8 + (d - '0');
                            i++;
                            count++;
                        }
                        sb.append((char) val);
                    } else {
                        sb.append(next);
                    }
                    break;
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

