int addConstantNameAndType(final String name,final String descriptor){
    if (name == null || descriptor == null) {
        throw new IllegalArgumentException("name and descriptor must not be null");
    }
    try {
        // key that uniquely identifies a NameAndType constant
        final String key = name + "\u0000" + descriptor;
        // We assume there is a field constantPoolMap that stores already added constants
        // and a list constantPoolList that keeps the insertion order to determine the index.
        // For the purpose of this method, we search the list first for an existing entry.
        for (int i = 0; i < constantPoolList.size(); i++) {
            Symbol s = constantPoolList.get(i);
            if (key.equals(s.getKey())) {
                return i; // already exists, return its index
            }
        }
        // Create a new Symbol and add it to the pool
        Symbol newSym = new Symbol(name, descriptor);
        constantPoolList.add(newSym);
        constantPoolMap.put(key, newSym);
        return constantPoolList.size() - 1; // index of the newly added constant
