        return false;
    }
    try {
        // Obtain adjacent nodes
        ListNodeImpl<E> prev = node.prev();
        ListNodeImpl<E> next = node.next();

        // Update the previous node's next reference
        if (prev != null) {
            prev.next(next);
        } else {
            // If there's no previous node, node was the head
            head = next;
        }

        // Update the next node's prev reference
        if (next != null) {
            next.prev(prev);
        } else {
            // If there's no next node, node was the tail
            tail = prev;
        }

        // Detach the node from the list
        node.prev(null);
        node.next(null);

        // Adjust the size counter if it's maintained
        if (size > 0) {
            size--;
        }
        return true;
