public void abbreviate(final int nameStart, final StringBuffer buf){
    try{
        if(buf == null){
            return;
        }
        if(nameStart < 0){
            return;
        }
        if(nameStart >= buf.length()){
            return;
        }
        String remaining = buf.substring(nameStart);
        if(remaining.isEmpty()){
            return;
        }
        String[] words = remaining.split("\\s+");
        if(words.length == 0){
            return;
        }
        StringBuilder abbreviation = new StringBuilder();
        for(String word : words){
            if(word.isEmpty()){
                continue;
            }
            abbreviation.append(word.charAt(0)).append('.');
        }
        if(abbreviation.length() > 0){
            buf.append(' ').append(abbreviation.toString());
        }
    }catch(Exception e){
        // silently ignore any unexpected exceptions
    }
}

