private static <V,E>boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (graph == null || vertices == null) {
        return false;
    }
    int size = vertices.size();
    if (size <= 1) {
        return true; // empty or single vertex is a clique
    }
    // Convert to list for index-based access
    List<V> vertexList = new ArrayList<>(vertices);
    for (int i = 0; i < size; i++) {
        V v1 = vertexList.get(i);
        for (int j = i + 1; j < size; j++) {
            V v2 = vertexList.get(j);
            if (graph.getEdge(v1, v2) == null && graph.getEdge(v2, v1) == null) {
                return false;
            }
        }
    }
    return true;
}

private List<Integer> computeLowerBounds(List<K> keys){
    List<Integer> lowerBounds = new ArrayList<>();
    if (keys == null) return lowerBounds;
    for (int i = 0; i < keys.size(); i++){
        K key = keys.get(i);
        if (key == null){
            lowerBounds.add(null);
            continue;
        }
        Integer maxLower = null;
        for (int j = 0; j < keys.size(); j++){
            if (i == j) continue;
            K other = keys.get(j);
            if (other == null) continue;
            try{
                Integer val = (Integer)other;
                Integer cur = (Integer)key;
                if (val < cur && (maxLower == null || val > maxLower)){
                    maxLower = val;
                }
            }catch(ClassCastException e){
                // skip non-Integer keys
                continue;
            }
        }
        lowerBounds.add(maxLower);
    }
    return lowerBounds;
}

private void pop(final String descriptor){
    if (descriptor == null || descriptor.isEmpty()) {
        return;
    }
    int idx = 0;
    // If descriptor starts with '(' treat as method descriptor
    if (descriptor.charAt(0) == '(') {
        idx = 1;
        while (idx < descriptor.length() && descriptor.charAt(idx) != ')') {
            int typeLen = parseTypeLength(descriptor, idx);
            char typeChar = descriptor.charAt(idx);
            // pop slots according to type
            int slots = (typeChar == 'J' || typeChar == 'D') ? 2 : 1;
            for (int s = 0; s < slots; s++) {
                outputFrameStack.pop();
            }
            idx += typeLen;
        }
        // skip ')' if present
        if (idx < descriptor.length() && descriptor.charAt(idx) == ')') {
            idx++;
        }
    } else {
        // Field or single type descriptor
        int typeLen = parseTypeLength(descriptor, idx);
        char typeChar = descriptor.charAt(idx);
        int slots = (typeChar == 'J' || typeChar == 'D') ? 2 : 1;
        for (int s = 0; s < slots; s++) {
            outputFrameStack.pop();
        }
    }
}

/**
 * Returns the number of characters that make up a single type in the descriptor
 * starting at {@code index}. Handles primitives, objects, and array types.
 */
private int parseTypeLength(String descriptor, int index) {
    char c = descriptor.charAt(index);
    if (c == '[') {
        // Count all '[' characters
        int i = index;
        while (descriptor.charAt(i) == '[') {
            i++;
        }
        // Skip the element type (either object or primitive)
        if (descriptor.charAt(i) == 'L') {
            i = indexOfEndOfObject(descriptor, i);
        }
        // Length from initial '[' to end of element type
        return i - index + 1;
    } else if (c == 'L') {
        return indexOfEndOfObject(descriptor, index) - index + 1;
    } else { // Primitive types: B, C, D, F, I, J, S, Z
        return 1;
    }
}

/**
 * Finds the index of the terminating ';' for an object type starting at {@code index}.
 */
private int indexOfEndOfObject(String descriptor, int index) {
    int i = index; // should be at 'L'
    while (descriptor.charAt(i) != ';') {
        i++;
    }
    return i;
}

