private void checkIfPackedField() throws IOException {
    // If the last read tag corresponds to a length-delimited field
    // for a repeated primitive, mark the state as reading a packed field.
    // Assume `lastTag` holds the most recent tag, `isRepeatedField(int)` checks repetition,
    // and `isReadingPacked` is the internal flag to update.
    if ((this.lastTag & 0x7) == 2 && this.isRepeatedField(this.lastTag >> 3)) {
        this.isReadingPacked = true;
    }
}

public int readTag() throws IOException {
    int tag = 0;
    int shift = 0;
    while (shift < 32) {
        int b = input.read();
        if (b == -1) {
            return 0;   // EOF reached
        }
        tag |= (b & 0x7F) << shift;
        if ((b & 0x80) == 0) {
            break;   // last byte of varint
        }
        shift += 7;
    }
    return tag;
}

