public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file,List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    if(file==null || !file.isFile()){
        throw new IllegalArgumentException("File must exist and be a regular file");
    }
    if(timeRanges==null || timeRanges.isEmpty()){
        return java.util.Collections.emptyList();
    }
    java.util.List<ThreadSnapshot> result = new java.util.ArrayList<>();
    try (java.io.BufferedReader br = new java.io.BufferedReader(new java.io.FileReader(file))) {
        String line;
        while ((line = br.readLine()) != null) {
            if (line.isEmpty()) continue;
            // Expected format: timestamp,<snapshot-data>
            int commaIdx = line.indexOf(',');
            if (commaIdx <= 0) continue;
            long ts;
            try {
                ts = Long.parseLong(line.substring(0, commaIdx).trim());
            } catch (NumberFormatException e) {
                continue; // skip malformed line
            }
            boolean inRange = false;
            for (ProfileAnalyzeTimeRange range : timeRanges) {
                if (range.contains(ts)) {
                    inRange = true;
                    break;
                }
            }
            if (!inRange) continue;
            String snapshotStr = line.substring(commaIdx + 1).trim();
            // Create ThreadSnapshot instance. The constructor and setters are assumed to exist.
            ThreadSnapshot tsnap;
            try {
                tsnap = new ThreadSnapshot(snapshotStr);
            } catch (Exception e) {
                // Fallback: use no-arg constructor and set fields via reflection if available
                tsnap = new ThreadSnapshot();
                try {
                    java.lang.reflect.Method setTs = ThreadSnapshot.class.getMethod("setTimestamp", long.class);
                    java.lang.reflect.Method setData = ThreadSnapshot.class.getMethod("setData", String.class);
                    setTs.invoke(tsnap, ts);
                    setData.invoke(tsnap, snapshotStr);
                } catch (Exception ex) {
                    // If reflection fails, skip this snapshot
                    continue;
                }
            }
            result.add(tsnap);
        }
    }
    return result;
}
